public class ValueRemoverCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(ValueRemover impl) {
        try {
            return ValueRemoverChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectRemover()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectRemover()));
        check("rejects the version that removes only the first match", false, verdict(new FirstOnlyRemover()));
        check("rejects the remove(int) that deletes by position instead of by value", false, verdict(new IndexOverloadRemover()));
        check("rejects the version that empties the caller's list", false, verdict(new DestructiveRemover()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectRemover implements ValueRemover {
    public java.util.List<Integer> without(java.util.List<Integer> values, int unwanted) {
        java.util.List<Integer> kept = new java.util.ArrayList<>();
        for (int value : values) {
            if (value != unwanted) kept.add(value);
        }
        return kept;
    }
}

class AlsoCorrectRemover implements ValueRemover {
    public java.util.List<Integer> without(java.util.List<Integer> values, int unwanted) {
        java.util.List<Integer> copy = new java.util.ArrayList<>(values);
        copy.removeIf(value -> value == unwanted);
        return copy;
    }
}

class FirstOnlyRemover implements ValueRemover {
    public java.util.List<Integer> without(java.util.List<Integer> values, int unwanted) {
        java.util.List<Integer> copy = new java.util.ArrayList<>(values);
        copy.remove(Integer.valueOf(unwanted));
        return copy;
    }
}

class IndexOverloadRemover implements ValueRemover {
    public java.util.List<Integer> without(java.util.List<Integer> values, int unwanted) {
        java.util.List<Integer> copy = new java.util.ArrayList<>(values);
        while (copy.contains(unwanted) && unwanted < copy.size()) {
            copy.remove(unwanted);
        }
        return copy;
    }
}

class DestructiveRemover implements ValueRemover {
    public java.util.List<Integer> without(java.util.List<Integer> values, int unwanted) {
        values.removeIf(value -> value == unwanted);
        return values;
    }
}

