/**
 * TASK: Write the checks that decide whether a ValueRemover is correct.
 *
 *   without(values, unwanted) returns a NEW list holding everything except
 *   unwanted, in the original order. EVERY occurrence goes, not just the first.
 *   The list passed in must not be modified. Removing a value that is not
 *   there simply returns a copy.
 *   Example: without([5, 2, 5, 7], 5) -> [2, 7]
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
import java.util.List;

interface ValueRemover {
    /* Provided -- do not edit. */
    List<Integer> without(List<Integer> values, int unwanted);
}

public class ValueRemoverChecker {

    public static boolean isCorrect(ValueRemover impl) {
        try {
            java.util.List<Integer> input =
                    new java.util.ArrayList<>(java.util.List.of(5, 2, 5, 7));
            java.util.List<Integer> result = impl.without(input, 5);
            if (!java.util.List.of(2, 7).equals(result)) return false;
            if (!java.util.List.of(5, 2, 5, 7).equals(input)) return false;

            if (!java.util.List.of(1, 2).equals(
                    impl.without(new java.util.ArrayList<>(java.util.List.of(1, 2)), 9))) return false;
            if (!java.util.List.of().equals(
                    impl.without(new java.util.ArrayList<>(java.util.List.of(4, 4)), 4))) return false;
            if (!java.util.List.of().equals(
                    impl.without(new java.util.ArrayList<>(), 1))) return false;
            if (!java.util.List.of(0, 3).equals(
                    impl.without(new java.util.ArrayList<>(java.util.List.of(0, 2, 3)), 2))) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
